/* @lc app=leetcode id=1494 lang=kotlin */ class Solution { fun minNumberOfSemesters(n: Int, relations: Array<IntArray>, k: Int): Int = IntArray(n).also { pre -> relations.forEach { pre[it[1] - 1] = pre[it[1] - 1] or (1 shl (it[0] - 1)) } }.let { pre -> IntArray(1 shl n) { 100 }.also { dp -> dp[0] = 0 }.also { dp -> (0 until (1 shl n)).forEach { mask -> if (dp[mask] != 100) (0 until n).filter { (mask and (1 shl it)) == 0 && (mask and pre[it]) == pre[it] }.fold(0) { a, i -> a or (1 shl i) }.let { avail -> generateSequence(avail) { (it - 1) and avail }.takeWhile { it > 0 }.forEach { sub -> if (sub.countOneBits() <= k) dp[mask or sub] = minOf(dp[mask or sub], dp[mask] + 1) } } } }[(1 shl n) - 1] } }